using System;
using System.Collections.Generic;

class Program
{
    // Fake identity store: token -> user name, user -> roles
    static Dictionary<string, string> tokens = new Dictionary<string, string> { { "tok-priya", "priya" }, { "tok-sam", "sam" } };
    static Dictionary<string, string[]> roles = new Dictionary<string, string[]> { { "priya", new[] { "Manager" } }, { "sam", new string[0] } };

    // Time O(1) per call, space O(1)
    static int Handle(string token, string neededRole)
    {
        // Authentication: who are you?
        string user;
        if (token == null || !tokens.TryGetValue(token, out user)) return 401;
        // Authorization: what may you do?
        if (Array.IndexOf(roles[user], neededRole) < 0) return 403;
        return 200;
    }

    static void Main()
    {
        string[] calls = { null, "tok-bad", "tok-sam", "tok-priya" };
        foreach (string t in calls)
            Console.WriteLine("token=" + (t ?? "none") + " needs Manager -> " + Handle(t, "Manager"));
    }
}

using System;

class Token
{
    public string Kind;      // "id", "access" or "refresh"
    public string Audience;  // who the token is meant for
    public string Scope;
}

class Program
{
    const string ApiAudience = "api://orders";

    // Time O(1), space O(1)
    static string ApiAccepts(Token t)
    {
        if (t.Kind == "refresh") return "reject: refresh tokens only go to the token endpoint";
        if (t.Audience != ApiAudience) return "reject 401: aud is " + t.Audience + ", not " + ApiAudience;
        if (t.Kind == "access" && t.Scope == "Orders.Read") return "accept: scope Orders.Read";
        return "reject: wrong kind or scope";
    }

    static void Main()
    {
        Token[] sent =
        {
            new Token { Kind = "id", Audience = "client-app-id" },
            new Token { Kind = "refresh", Audience = "token-endpoint" },
            new Token { Kind = "access", Audience = ApiAudience, Scope = "Orders.Read" },
        };
        foreach (var t in sent)
            Console.WriteLine(t.Kind + " token -> " + ApiAccepts(t));
    }
}

using System;
