class Program
{
    static string B64Url(string s)
    {
        return Convert.ToBase64String(Encoding.UTF8.GetBytes(s)).TrimEnd('=').Replace('+', '-').Replace('/', '_');
    }

    static string Decode(string part)
    {
        string p = part.Replace('-', '+').Replace('_', '/');
        while (p.Length % 4 != 0) p += "=";            // restore Base64 padding
        return Encoding.UTF8.GetString(Convert.FromBase64String(p));
    }

    // Time O(n) in token length, space O(n)
    static void Main()
    {
        string header = "{\"alg\":\"RS256\",\"kid\":\"key-1\"}";
        string payload = "{\"iss\":\"https://issuer.example\",\"aud\":\"api://orders\",\"oid\":\"u-001\",\"exp\":1900000000}";
        string token = B64Url(header) + "." + B64Url(payload) + ".c2ln";   // fake signature
        Console.WriteLine("token  = " + token);

        string[] parts = token.Split('.');
        Console.WriteLine("header = " + Decode(parts[0]));
        Console.WriteLine("payload= " + Decode(parts[1]));
        // Anyone can read this. Nothing here proved the signature is genuine.
        Console.WriteLine("signature checked? NO - decoding is not validating");
    }
}

using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

class Program
{
    static Dictionary<string, RSA> keyCache = new Dictionary<string, RSA>();   // kid -> public key
    static int downloads = 0;

    // Pretend JWKS download: only called when kid is unknown
    static void RefreshKeys(Dictionary<string, RSA> published)
    {
        downloads++;
        foreach (var kv in published) keyCache[kv.Key] = kv.Value;
    }

    // Verify is local CPU work: O(1) per token, no network
    static bool Verify(string kid, byte[] data, byte[] sig, Dictionary<string, RSA> published)
    {
        if (!keyCache.ContainsKey(kid)) RefreshKeys(published);   // rotation: refresh once
        if (!keyCache.ContainsKey(kid)) return false;
        return keyCache[kid].VerifyData(data, sig, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1);
    }

    static void Main()
    {
        RSA issuerKey = RSA.Create(2048);   // the identity provider's private key
        var published = new Dictionary<string, RSA> { { "key-1", RSA.Create() } };
        published["key-1"].ImportParameters(issuerKey.ExportParameters(false));
        byte[] data = Encoding.UTF8.GetBytes("header.payload");
        byte[] sig = issuerKey.SignData(data, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1);

        for (int i = 1; i <= 3; i++)
            Console.WriteLine("request " + i + " valid=" + Verify("key-1", data, sig, published) + " downloads=" + downloads);
        Console.WriteLine("unknown kid valid=" + Verify("key-9", data, sig, published) + " downloads=" + downloads);
    }
}

