class Program
{
    static HashSet<string> allowedTenants = new HashSet<string> { "tenant-a", "tenant-b" };

    // Issuer must be the issuer pattern for the tenant id carried in the token itself.
    // Time O(1), space O(1)
    static string Validate(string iss, string tid)
    {
        string expected = "https://login.example/" + tid + "/v2.0";
        if (iss != expected) return "reject: issuer does not match tid";
        if (!allowedTenants.Contains(tid)) return "reject: tenant not allowed";
        return "accept tenant " + tid;
    }

    static void Main()
    {
        Console.WriteLine(Validate("https://login.example/tenant-a/v2.0", "tenant-a"));
        Console.WriteLine(Validate("https://login.example/tenant-z/v2.0", "tenant-z"));   // valid token, unknown customer
        Console.WriteLine(Validate("https://login.example/tenant-a/v2.0", "tenant-b"));   // tid lies about the issuer
    }
}

