using System;
using System.Security.Cryptography;
using System.Text;

class Program
{
    static string B64Url(byte[] b)
    {
        return Convert.ToBase64String(b).TrimEnd('=').Replace('+', '-').Replace('/', '_');
    }

    static string Challenge(string verifier)
    {
        using (var sha = SHA256.Create())
            return B64Url(sha.ComputeHash(Encoding.ASCII.GetBytes(verifier)));   // S256
    }

    // Time O(n) for hashing a short string, space O(1)
    static void Main()
    {
        // 1. The app makes a random secret and keeps it, sends only the hash
        var rnd = new byte[32];
        using (var r = RandomNumberGenerator.Create()) r.GetBytes(rnd);
        string verifier = B64Url(rnd);
        string challenge = Challenge(verifier);
        Console.WriteLine("code_challenge sent in the browser: " + challenge);

        // 2. The server stored the challenge with the issued code. Later it checks the verifier.
        Console.WriteLine("real app redeems code: " + (Challenge(verifier) == challenge));
        Console.WriteLine("thief with stolen code, no verifier: " + (Challenge("guess") == challenge));
    }
}

