using System;

class Jwt
{
    public string Iss, Aud, Scp;
    public long Exp, Nbf;
    public bool SignatureOk;
}

class Program
{
    const long SkewSeconds = 300;   // 5 minutes tolerance

    // Time O(1), space O(1); no memory of earlier requests
    static string Validate(Jwt t, long now)
    {
        if (!t.SignatureOk) return "401 bad signature";
        if (t.Iss != "https://issuer.example/tenant/v2.0") return "401 wrong issuer";
        if (t.Aud != "api://orders") return "401 wrong audience";
        if (now > t.Exp + SkewSeconds) return "401 expired";
        if (now + SkewSeconds < t.Nbf) return "401 not valid yet";
        if (t.Scp != "Orders.Read") return "403 missing scope";
        return "200 OK";
    }

    static void Main()
    {
        long now = 1000000;
        var good = new Jwt { SignatureOk = true, Iss = "https://issuer.example/tenant/v2.0", Aud = "api://orders", Scp = "Orders.Read", Exp = now + 3600, Nbf = now - 10 };
        Console.WriteLine("good:    " + Validate(good, now));
        Console.WriteLine("expired: " + Validate(good, now + 4000));
        good.Aud = "api://other";
        Console.WriteLine("wrong aud: " + Validate(good, now));
    }
}

