let now = 0;                       // seconds
let cache = { token: "at-1", expiresAt: 3600 };
let refreshCalls = 0;

function refreshWithRefreshToken() {
  refreshCalls++;
  return { token: "at-" + (refreshCalls + 1), expiresAt: now + 3600 };
}

function acquireTokenSilent() {
  // Return the cached token while it is still good (with 5 minutes margin)
  if (cache && cache.expiresAt - now > 300) return cache.token + " (from cache)";
  // Otherwise use the refresh token, no user action needed
  cache = refreshWithRefreshToken();
  return cache.token + " (renewed)";
}

