using System;
using System.Collections.Generic;

class Info { public string User; public string Tenant; public long CachedUntil; }

class Program
{
    static int identityCalls = 0;
    static Dictionary<string, Info> cache = new Dictionary<string, Info>();

    // The identity service ("who is this?"); the token itself says nothing
    static Info Introspect(string token)
    {
        identityCalls++;
        return token == "sess-777" ? new Info { User = "priya", Tenant = "t1" } : null;
    }

    // Time O(1) average, space O(n) for n cached tokens
    static string Authenticate(string token, long now)
    {
        Info i;
        if (!cache.TryGetValue(token, out i) || i.CachedUntil < now)
        {
            i = Introspect(token);
            if (i == null) return "401";
            i.CachedUntil = now + 30;      // short TTL limits the revocation delay
            cache[token] = i;
        }
        return i.User + "@" + i.Tenant;
    }

    static void Main()
    {
        long[] times = { 0, 5, 10, 40 };
        foreach (long t in times) Console.WriteLine("t=" + t + " -> " + Authenticate("sess-777", t));
        Console.WriteLine("bad token -> " + Authenticate("nope", 0));
        Console.WriteLine("identity service calls: " + identityCalls);
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static HashSet<string> deniedSessions = new HashSet<string>();

    // A JWT is checked by expiry; the optional deny list adds one lookup. O(1) time.
    static string Check(string sid, long exp, long now)
    {
        if (now >= exp) return "401 expired";
        if (deniedSessions.Contains(sid)) return "401 revoked";
        return "200 OK";
    }

    static void Main()
    {
        long issued = 0, exp = 3600;   // 60 minute token
        Console.WriteLine("t=100 normal:           " + Check("s1", exp, 100));
        // account disabled at t=200, refresh tokens are stopped by the identity provider
        Console.WriteLine("t=300 no deny list:     " + Check("s1", exp, 300) + "  <- still works until expiry");
        deniedSessions.Add("s1");
        Console.WriteLine("t=300 with deny list:   " + Check("s1", exp, 300));
        Console.WriteLine("t=4000 expired anyway:  " + Check("s2", exp, 4000));
    }
}

