// A tiny HTTP client with interceptors (like axios). Time O(i) per call for i interceptors.
const interceptors = [];
const client = {
  use(fn) { interceptors.push(fn); },
  async get(url) {
    let req = { url, headers: {} };
    for (const fn of interceptors) req = await fn(req);   // each can change the request
    return "GET " + req.url + " headers=" + JSON.stringify(req.headers);
  }
};

// Stand-in for acquireTokenSilent
async function getAccessToken() { return "eyJ.fake.token"; }

client.use(async (req) => {
  // Only our own API gets the token. Never send it to a third party.
  if (req.url.startsWith("https://api.contoso.example/")) {
    req.headers.Authorization = "Bearer " + (await getAccessToken());
  }
  req.headers["X-Correlation-ID"] = "id-" + (req.url.length);
  return req;
});

