// Time O(1) per caller, space O(1). One shared promise is the whole trick.
let refreshCalls = 0;
let refreshing = null;

function getNewToken() {
  refreshCalls++;
  return new Promise((resolve) => setTimeout(() => resolve("new-token"), 50));
}

function refreshOnce() {
  if (!refreshing) {
    refreshing = getNewToken().finally(() => { refreshing = null; });
  }
  return refreshing;   // everyone awaits the same promise
}

async function callApi(id) {
  // pretend the first try failed with 401, so we refresh and retry once
  const token = await refreshOnce();
  return "request " + id + " retried with " + token;
}

(async () => {
  const results = await Promise.all([1, 2, 3, 4, 5].map(callApi));
  results.forEach((r) => console.log(r));
  console.log("token refresh calls: " + refreshCalls);
})();

