using System;
using System.Collections.Generic;

class Ctx { public string Token; public string User; public bool NeedsAuth = true; public string Result; }

class Program
{
    delegate void Next();

    static void Main()
    {
        Console.WriteLine("correct order:  " + Run(new[] { "authn", "authz" }, "tok-priya"));
        Console.WriteLine("authz first:    " + Run(new[] { "authz", "authn" }, "tok-priya"));
        Console.WriteLine("no token:       " + Run(new[] { "authn", "authz" }, null));
    }

    // Time O(m) for m middlewares, space O(m)
    static string Run(string[] order, string token)
    {
        var c = new Ctx { Token = token };
        int i = 0;
        Next next = null;
        next = () =>
        {
            if (c.Result != null) return;
            if (i >= order.Length) { c.Result = "200 endpoint ran for " + c.User; return; }
            string name = order[i++];
            if (name == "authn") { if (c.Token == "tok-priya") c.User = "priya"; }   // fills User
            else if (c.NeedsAuth && c.User == null) { c.Result = "401 (authz saw no user)"; return; }
            next();
        };
        next();
        return c.Result;
    }
}

