using System;
using System.Collections.Generic;

class Caller { public string[] Roles; public decimal RefundLimit; public bool Mfa; }

class Program
{
    // Each handler returns: 1 = succeed, 0 = no opinion, -1 = explicit fail
    delegate int Handler(Caller c, decimal amount);

    // Time O(h) for h handlers, space O(1)
    static bool CanRefund(Caller c, decimal amount, List<Handler> handlers)
    {
        bool anySucceed = false;
        foreach (var h in handlers)
        {
            int r = h(c, amount);
            if (r < 0) return false;   // an explicit fail always wins
            if (r > 0) anySucceed = true;
        }
        return anySucceed;
    }

    static void Main()
    {
        var handlers = new List<Handler>
        {
            (c, a) => Array.IndexOf(c.Roles, "Manager") >= 0 ? 1 : 0,
            (c, a) => a <= c.RefundLimit ? 1 : -1,        // limit is a hard rule
            (c, a) => a > 500 && !c.Mfa ? -1 : 0,         // big refunds need MFA
        };
        var priya = new Caller { Roles = new[] { "Manager" }, RefundLimit = 1000, Mfa = true };
        Console.WriteLine("refund 200:  " + CanRefund(priya, 200, handlers));
        Console.WriteLine("refund 2000: " + CanRefund(priya, 2000, handlers));
        priya.Mfa = false;
        Console.WriteLine("refund 700 without MFA: " + CanRefund(priya, 700, handlers));
    }
}

using System;
using System.Security.Cryptography;
using System.Text;

class Program
{
    static byte[] key = Encoding.UTF8.GetBytes("demo-secret-from-key-vault-32bytes!");

    static string B64(byte[] b) { return Convert.ToBase64String(b).TrimEnd('=').Replace('+', '-').Replace('/', '_'); }

    static string Sign(string data)
    {
        using (var h = new HMACSHA256(key)) return B64(h.ComputeHash(Encoding.UTF8.GetBytes(data)));
    }

    static string Issue(string alg, string payload)
    {
        string head = B64(Encoding.UTF8.GetBytes("{\"alg\":\"" + alg + "\"}"));
        string body = B64(Encoding.UTF8.GetBytes(payload));
        return head + "." + body + "." + (alg == "none" ? "" : Sign(head + "." + body));
    }

    // Time O(n) in token size, space O(n). The API picks the algorithm, not the token.
    static string Verify(string token)
    {
        string[] p = token.Split('.');
        string h64 = p[0].Replace('-', '+').Replace('_', '/');
        while (h64.Length % 4 != 0) h64 += "=";
        string head = Encoding.UTF8.GetString(Convert.FromBase64String(h64));
        if (!head.Contains("HS256")) return "reject: algorithm not allowed";
        return Sign(p[0] + "." + p[1]) == p[2] ? "accept" : "reject: bad signature";
    }

    static void Main()
    {
        string good = Issue("HS256", "{\"sub\":\"u1\",\"exp\":1900000000}");
        Console.WriteLine("good token:     " + Verify(good));
        Console.WriteLine("alg none token: " + Verify(Issue("none", "{\"sub\":\"admin\"}")));
        string[] parts = good.Split('.');
        Console.WriteLine("edited payload: " + Verify(parts[0] + "." + B64(Encoding.UTF8.GetBytes("{\"sub\":\"admin\"}")) + "." + parts[2]));
    }
}

using System;
using System.Collections.Generic;

class Program
{
    // scheme name -> the only issuer that scheme trusts
    static Dictionary<string, string> schemes = new Dictionary<string, string>
    {
        { "Staff", "https://staff-idp.example/v2.0" },
        { "Customers", "https://customer-idp.example/" },
    };

    // A policy lists the schemes it accepts. Time O(s) for s schemes, space O(1).
    static string Authorize(string tokenIssuer, string tokenRole, string[] policySchemes)
    {
        foreach (string s in policySchemes)
            if (schemes[s] == tokenIssuer)
                return tokenRole == "Admin" && s != "Staff" ? "403 role not valid for this issuer" : "200 via scheme " + s;
        return "401 issuer not accepted by this policy";
    }

    static void Main()
    {
        string[] staffOnly = { "Staff" };
        string[] both = { "Staff", "Customers" };
        Console.WriteLine("staff token, staff policy:     " + Authorize("https://staff-idp.example/v2.0", "Admin", staffOnly));
        Console.WriteLine("customer token, staff policy:  " + Authorize("https://customer-idp.example/", "Customer", staffOnly));
        Console.WriteLine("customer token, both policy:   " + Authorize("https://customer-idp.example/", "Customer", both));
        Console.WriteLine("customer claims Admin role:    " + Authorize("https://customer-idp.example/", "Admin", both));
    }
}

