using System;
using System.Collections.Generic;

class Program
{
    // Time O(1), space O(1). Real systems read these from the decoded (never logged) token.
    static string Diagnose(string aud, string ver, long exp, long now, string scp)
    {
        if (aud != "api://orders") return "401: aud mismatch - token for another API, or an ID token";
        if (ver != "2.0") return "401: issuer mismatch - v1.0 token sent to a v2.0 API";
        if (now > exp + 300) return "401: expired (check refresh logic and server clock)";
        if (scp == null || !scp.Contains("Orders.Read")) return "403: scope missing - consent or request scopes";
        return "token looks fine - look at roles, tenant and data rules";
    }

    static void Main()
    {
        long now = 10000;
        Console.WriteLine(Diagnose("client-id", "2.0", now + 600, now, "Orders.Read"));
        Console.WriteLine(Diagnose("api://orders", "1.0", now + 600, now, "Orders.Read"));
        Console.WriteLine(Diagnose("api://orders", "2.0", now - 900, now, "Orders.Read"));
        Console.WriteLine(Diagnose("api://orders", "2.0", now + 600, now, "Other.Read"));
        Console.WriteLine(Diagnose("api://orders", "2.0", now + 600, now, "Orders.Read"));
    }
}

using System;
using System.Collections.Generic;

class Principal { public string Oid; public string[] Roles; }

class Server
{
    public string Name;
    public int Requests;
    // Same validation code and same cached public keys on every server. Time O(1), space O(1)
    public Principal Handle(Dictionary<string, string> claims)
    {
        Requests++;
        return new Principal { Oid = claims["oid"], Roles = claims["roles"].Split(',') };   // lives for this request only
    }
}

class Program
{
    static void Main()
    {
        var farm = new[] { new Server { Name = "A" }, new Server { Name = "B" }, new Server { Name = "C" } };
        var claims = new Dictionary<string, string> { { "oid", "u-001" }, { "roles", "Reader,Manager" } };

        for (int i = 0; i < 6; i++)
        {
            Server s = farm[i % 3];   // a load balancer, no sticky sessions
            Principal p = s.Handle(claims);
            Console.WriteLine("request " + (i + 1) + " -> server " + s.Name + ": user " + p.Oid + " roles " + string.Join("+", p.Roles));
        }
    }
}

