// An interceptor is a plain function, so it is easy to test. Time O(1), space O(1).
function makeInterceptor(getToken, apiOrigin) {
  return async (req) => {
    if (new URL(req.url).origin === apiOrigin) {
      req.headers = Object.assign({}, req.headers, { Authorization: "Bearer " + (await getToken()) });
    }
    return req;
  };
}

let passed = 0;
function check(name, ok) { console.log((ok ? "PASS " : "FAIL ") + name); if (ok) passed++; }

(async () => {
  const intercept = makeInterceptor(async () => "fake-token", "https://api.contoso.example");

  const own = await intercept({ url: "https://api.contoso.example/orders", headers: {} });
  check("adds token to own API", own.headers.Authorization === "Bearer fake-token");

  const other = await intercept({ url: "https://evil.example/x", headers: {} });
  check("no token for other host", other.headers.Authorization === undefined);

  const lookalike = await intercept({ url: "https://api.contoso.example.evil.example/", headers: {} });
  check("no token for look-alike host", lookalike.headers.Authorization === undefined);
  console.log(passed + " of 3 passed");
})();

