using System;
using System.Diagnostics;
using System.Security.Cryptography;
using System.Text;

class Program
{
    static byte[] Hash(string pw, byte[] salt, int iterations)
    {
        using (var k = new Rfc2898DeriveBytes(pw, salt, iterations, HashAlgorithmName.SHA256))
            return k.GetBytes(32);
    }

    // Cost grows linearly with iterations; space O(1)
    static void Main()
    {
        byte[] salt = new byte[16];
        using (var r = RandomNumberGenerator.Create()) r.GetBytes(salt);   // unique random salt per password

        foreach (int it in new[] { 1, 10000, 600000 })
        {
            var sw = Stopwatch.StartNew();
            Hash("correct horse battery", salt, it);
            sw.Stop();
            Console.WriteLine("iterations=" + it + " -> slow enough for an attacker? " + (it >= 600000 ? "yes" : "no"));
        }
        // Same password + different salt = different hash, so rainbow tables fail
        byte[] salt2 = new byte[16];
        Console.WriteLine("same password, different salt equal? " + (Convert.ToBase64String(Hash("pw", salt, 1000)) == Convert.ToBase64String(Hash("pw", salt2, 1000))));
    }
}
